do $$
declare
  v_creator uuid;
  v_customer uuid;
  v_offer uuid;
  v_seq int;
  v_offer_no text;
begin
  select id into v_creator from public.profiles where email = 'scolakoglu@orioncranes.com' limit 1;
  if v_creator is null then
    select id into v_creator from public.profiles where role::text = 'admin' order by created_at limit 1;
  end if;
  if v_creator is null then raise exception 'Geçmiş teklif aktarımı için yönetici profili bulunamadı'; end if;

  select id into v_customer from public.customers
  where short_name ilike '%İSDEMİR%' or name ilike '%İSDEMİR%'
  order by (short_name ilike '%İSDEMİR%') desc, created_at limit 1;
  if v_customer is null then raise exception 'İSDEMİR müşteri kaydı bulunamadı'; end if;

  select id into v_offer from public.offers
  where customer_id = v_customer and issue_date = date '2026-06-03' and subject = 'SD-11 NOLU VİNCİN SÜRÜCÜ VE OTOMASYON SİSTEMLERİNİN YENİLENMESİ'
  order by created_at limit 1;

  if v_offer is null then
    select coalesce(max(seq), 0) + 1 into v_seq from public.offers where lang = 'tr' and issue_date = date '2026-06-03';
    v_offer_no := 'TETR-' || to_char(date '2026-06-03', 'YYYYMMDD') || '-' || v_seq::text;
    insert into public.offers (offer_no, lang, issue_date, seq, issued_on, customer_id, customer_name, subject, status, currency, created_by, created_at, updated_at)
    values (v_offer_no, 'tr', date '2026-06-03', v_seq, date '2026-06-03', v_customer, 'İSDEMİR', 'SD-11 NOLU VİNCİN SÜRÜCÜ VE OTOMASYON SİSTEMLERİNİN YENİLENMESİ', 'sent', 'EUR', v_creator, timestamptz '2026-06-03 12:00:00+03', timestamptz '2026-06-03 12:00:00+03')
    returning id into v_offer;
