.","direct":1554345,"total":1849670.55}$cost$::jsonb, 'Kaynak belgeden geçmiş maliyet aktarımı', v_creator, timestamptz '2026-07-31 12:00:00+03', timestamptz '2026-07-31 12:00:00+03', timestamptz '2026-07-31 12:00:00+03', v_creator)
  on conflict (offer_id, rev_no) do nothing;
end
$$;


do $$
declare
  v_creator uuid;
  v_customer uuid;
  v_offer uuid;
  v_seq int;
  v_offer_no text;
begin
  select id into v_creator from public.profiles where email = 'scolakoglu@orioncranes.com' limit 1;
  if v_creator is null then
    select id into v_creator from public.profiles where role::text = 'admin' order by created_at limit 1;
  end if;
  if v_creator is null then raise exception 'Geçmiş teklif aktarımı için yönetici profili bulunamadı'; end if;

  select id into v_customer from public.customers
  where short_name ilike '%ERDEMİR%' or name ilike '%ERDEMİR%'
  order by (short_name ilike '%ERDEMİR%') desc, created_at limit 1;
  if v_customer is null then raise exception 'ERDEMİR müşteri kaydı bulunamadı'; end if;

  select id into v_offer from public.offers
  where customer_id = v_customer and issue_date = date '2026-08-29' and subject = 'CC16 VE CC17 50/10 MT VİNÇLERİ MODERNİZASYONU'
  order by created_at limit 1;

  if v_offer is null then
    select coalesce(max(seq), 0) + 1 into v_seq from public.offers where lang = 'tr' and issue_date = date '2026-08-29';
    v_offer_no := 'TETR-' || to_char(date '2026-08-29', 'YYYYMMDD') || '-' || v_seq::text;
    insert into public.offers (offer_no, lang, issue_date, seq, issued_on, customer_id, customer_name, subject, status, currency, created_by, created_at, updated_at)
    values (v_offer_no, 'tr', date '2026-08-29', v_seq, date '2026-08-29', v_customer, 'ERDEMİR', 'CC16 VE CC17 50/10 MT VİNÇLERİ MODERNİZASYONU', 'sent', 'EUR', v_creator, timestamptz '2026-08-29 12:00:00+03', timestamptz '2026-08-29 12:00:00+03')
    returning id into v_offer;
  end if;

  insert into public.offer_revisions (offer_id, rev_no, label, status, payload, notes, created_by, created_at, updated_at, issued_at, issued_by)
