  insert into public.offer_cost_revisions (offer_id, rev_no, label, status, payload, notes, created_by, created_at, updated_at, issued_at, issued_by)
  values (v_offer, 0, '', 'issued', $cost${"version":6,"sourceRevNo":0,"currency":"EUR","params":{},"materialPrices":{},"items":[{"id":"8c9ab20c-f086-5423-9c7d-484f9c9dfd2a","offerItemId":"e194fb6c-23c4-5ec8-86ac-438110a24796","title":"CC16 VE CC17 50/10 MT VİNÇLERİ MODERNİZASYONU","craneType":"Vinç Modernizasyonu","qty":1,"inputs":{},"overrides":{},"groups":[{"id":"7b2f0a63-b0db-5147-bf23-7bdd0ade85ba","key":"aktarim-cc16-17-1","title":"Hazır Ekipman","lump":false,"lines":[{"id":"24357c3a-9faf-5641-ae47-3de9bcc2b5c6","key":"aktarim-cc16-17-3","label":"Ana Kaldırma Motoru","qty":2,"qtyManual":true,"unit":"adet","unitPrice":11500,"priceManual":true,"note":"min. 110 kW, 750 d/dk (8 kutuplu), 400V AC 3F+T 50Hz, F izolasyon / S1 / IE4, min. IP65, döküm gövde, metal fanlı (harici soğutma yok), izoleli rulman, her sargıda 3 uçlu PT100, vibrasyon sensörü, fabrika çıkışlı enkoder mili, topraklama cıvatası + kaldırma kulağı; 60°C ortam ve tozlu koşullara göre derate (Şartname 3.3.3) · SIEMENS / ABB / LEROY SOMER / SEW · Tahmini","hidden":false},{"id":"76441a13-8801-5d47-9975-e20c5881f120","key":"aktarim-cc16-17-4","label":"Yardımcı Kaldırma Motoru","qty":2,"qtyManual":true,"unit":"adet","unitPrice":5000,"priceManual":true,"note":"min. 22 kW, 1000 d/dk (6 kutuplu), F / S1 / IE4, min. IP65, döküm gövde, metal fanlı, izoleli rulman, 3 uçlu PT100, vibrasyon sensörü, enkoder milli (Şartname 3.3.3) · SIEMENS / ABB / LEROY SOMER / SEW · Tahmini","hidden":false},{"id":"139ef59f-dd8a-5b23-8743-b3ef47d2ffca","key":"aktarim-cc16-17-5","label":"Köprü Yürütme Motorları","qty":4,"qtyManual":true,"unit":"adet","unitPrice":3900,"priceManual":true,"note":"min. 2×22 kW, 1500 d/dk (4 kutuplu), F / S1 / IE4, min. IP65, döküm gövde, metal fanlı, 3 uçlu PT100, enkoder milli; yürütme motor hesapları CMAA standardına göre yapılıp onaya sunulacak (Şartname 3.3.3, 3.2.1/7) · SIEMENS / ABB / LEROY SOMER / SEW · Tahmini","hidden":false},{"id":"81269078-7706-5165-9b3a-080ff18b8877","key":"aktarim-cc16-17-6","label":"Araba Yürütme Motoru","qty":2,"qtyManual":true,"unit":"adet","unitPrice":2800,"priceManual":true,"note":"min. 15 kW, 1500 d/dk (4 kutuplu), F / S1 / IE4, min. IP65, döküm gövde, metal fanlı, 3 uçlu PT100, enkoder milli (Şartname 3.3.3) · SIEMENS / ABB / LEROY SOMER / SEW · Tahmini","hidden":false},{"id":"e1951521-a175-5c16-a01c-17e01e5e900b","key":"aktarim-cc16-17-7","label":"Ana Kaldırma Eldro Frenleri","qty":4,"qtyManual":true,"unit":"adet","unitPrice":2300,"priceManual":true,"note":"Vinç başına 2 adet; ELDRO tip, içten yaylı, debi ayarlı fren motoru, asbestsiz yapıştırmalı balata, S3 %60 ED, min. IP65, 400V AC 3P+E; tam yükte frenleme torkunun %250'sini karşılayacak limit tork; elle açma sistemi; 3 uçlu led göstergeli açık/kapalı izleme sensörü (Şartname 3.3.4) · SİBRE / STROMAG (Avrupa menşeli) · Tahmini","hidden":false},{"id":"3c3b6c7e-e2a0-5c5a-a068-2286915abb48","key":"aktarim-cc16-17-8","label":"Yardımcı Kaldırma Eldro Frenleri","qty":4,"qtyManual":true,"unit":"adet","unitPrice":1800,"priceManual":true,"note":"Vinç başına 2 adet; ELDRO tip, içten yaylı, asbestsiz yapıştırmalı balata, S3 %60 ED, min. IP65, elle açma, led göstergeli izleme sensörü (Şartname 3.3.4) · SİBRE / STROMAG (Avrupa menşeli) · Tahmini","hidden":false},{"id":"ade17b65-01c1-519f-bb82-1cf55f5f6317","key":"aktarim-cc16-17-9","label":"Köprü & Araba Yürütme Eldro Frenleri","qty":6,"qtyManual":true,"unit":"adet","unitPrice":1250,"priceManual":true,"note":"Vinç başına köprü 2 + araba 1 = 3 adet; motor moment değeri üzerinden min. 2 kat (%200) emniyet katsayısı; ELDRO tip, S3 %60 ED, min. IP65, elle açma, led göstergeli izleme sensörü (Şartname 3.3.4/5) · SİBRE / STROMAG (Avrupa menşeli) · Tahmini","hidden":false},{"id":"22236750-3267-5bb6-920e-9e6cebdb99c1","key":"aktarim-cc16-17-10","label":"Fren Kasnakları & Ara Şaftlar","qty":2,"qtyManual":true,"unit":"takım","unitPrice":1000,"priceManual":true,"note":"Köprü ve araba yürütmede motor–redüktör arası kaplin bağlantısı ve eldro fren kasnağı; ana/yardımcı kaldırma fren kasnakları; ara şaftlar. Kasnaklar montaj yerine kolayca monte edilebilir özellikte (Şartname 3.2.1/5-6, 3.3.4/6) · Orion / FLENDER / GOSAN · Tahmini","hidden":false},{"id":"3a07bf53-f293-5c02-986c-32cbecfa7155","key":"aktarim-cc16-17-11","label":"Kaplinler (Küresel Dişli Elastik)","qty":2,"qtyManual":true,"unit":"takım","unitPrice":6200,"priceManual":true,"note":"Ana kaldırma motor–redüktör kaplini, yardımcı kaldırma dişli elastik tambur kaplini, köprü yürütme (2 adet) ve araba yürütme kaplinleri; maksimum torka göre tasarım, yürütmede min. 2 / kaldırmada min. 2,5 emniyet katsayısı, gresörlüklü, keçeli (O-ring kullanılmayacak), doğrudan kasnağa değil mil üzerine montaj (Şartname 3.2.3) · FLENDER / GOSAN / MAİNA / ESCO GEAR · Tahmini","hidden":false},{"id":"00e39e4e-41eb-5f51-8b73-3ddf981d5f81","key":"aktarim-cc16-17-15","label":"Pin Tipi Loadcell (Ana + Yardımcı Kanca)","qty":4,"qtyManual":true,"unit":"adet","unitPrice":500,"priceManual":true,"note":"Denge traversi ana milinde yağlama kanallı pin tipi loadcell, her denge traversinde 1 adet; ISO 376 (OIML Class R60) test raporlu, doğrusal olmama hatası <%0,25 (lineerlik+histerezis <%0,4), tekrarlanabilirlik ±%0,1, IP67 (DIN 60529), -25/+80°C işletme; nominal yükte gelen kuvvetin min. 2 katı; kabul edilebilir aşırı yük ≥%150, ayrılma yükü ≥%500 (Şartname 3.2.2/2, 3.3.13/14) · ESİT · Tahmini","hidden":false},{"id":"62796329-5c25-50c0-9322-2f76fba74aa9","key":"aktarim-cc16-17-16","label":"Elektronik Aşırı Yük Koruma İndikatörü","qty":4,"qtyManual":true,"unit":"adet","unitPrice":250,"priceManual":true,"note":"Ana ve yardımcı kanca için ayrı ayrı; dijital giriş/çıkış, 4-20 mA analog çıkış PLC'ye; yazılımda %110 rampalı ve %125 hızlı rampalı durdurma sinyalleri, ayarlanabilir gecikme süreleri; ağırlık bilgisi kabinden ve SCADA üzerinden eş zamanlı izlenebilir (Şartname 3.3.8/42, 3.3.13/15) · ESİT · Tahmini","hidden":false},{"id":"d9cd115d-e6d8-5515-893b-7bf943328c3c","key":"aktarim-cc16-17-21","label":"FM200 Gazlı Yangın Söndürme Sistemi","qty":2,"qtyManual":true,"unit":"takım","unitPrice":500,"priceManual":true,"note":"Elektrik odası için FM200 gazlı söndürme sistemi; panel gözlerine yukarıdan püskürtme boru sistemi, otomatik devreye girme (kontak bilgisi), basınç anahtarı, dedektör ve lokal güç kaynağı; yangın durumunda panel tepe fan/filtre ve elektrik oda klima sisteminin durdurulması; kontak bilgileri fiziksel bağlantı + PLC girişi (Şartname 3.3.8/43, 3.3.11/18, Soru Formu 5.39) · EMA · Tahmini","hidden":false},{"id":"a7e0aaaf-f6a8-5c93-8908-c7d571612ab6","key":"aktarim-cc16-17-22","label":"Telsiz Telefon Sistemi (Elektrik Odası ↔ Operatör Kabini)","qty":2,"qtyManual":true,"unit":"takım","unitPrice":300,"priceManual":true,"note":"Elektrik odası ve operatör kabini arasında haberleşme için her iki tarafa telsiz telefon; işletmenin Femko sistemi ile frekans karışmasını önleyecek ayarlama (Şartname 3.3.11/13-14) · - · Tahmini","hidden":false},{"id":"20f11b07-2cbf-5814-b73d-0855f8c834fb","key":"aktarim-cc16-17-23","label":"Panolar","qty":2,"qtyManual":true,"unit":"takım","unitPrice":8000,"priceManual":true,"note":"Elektrik odası içi eksen bazlı paneller LVD01 (ana besleme/ana kontaktör), LVD0 (yardımcı besleme), LVD02 (ISU), LVD1 (ana yük), LVD2 (yardımcı yük), LVD3 (araba yürütme), LVD4 (portal köprü yürütme), LVD10 (PLC/CPU) — min. IP23, min. 600 mm genişlik, ≥1000 mm kapaklar 2 parça, ≥2 mm DKP kapak/kapı, galvaniz profil, poliüretan conta, RAL 7035 elektrostatik boya, çok noktadan kilit (döküm menteşe yok), kapak–gövde ≥10 mm² fleksibıl bakır topraklama, kapak açılınca devreye giren prizli LED armatür (30 mA RCBO), tepe fan/filtre, >30 kg ekipman için raylı-tekerlekli çıkarma sistemi, plastik kablo kanalı, klemensler %20 fazla, şalter canlı uç izolasyon koruması, DC ve topraklama barası mika cam koruması. Elektrik odası dışında giriş kesici paneli SD1 — monoblok IP66, alttan çelik rekor+spiral giriş, kapak açılınca LED armatür, I/V/THD/kW/kVAR analizörü (min. 1 ay veri saklama), ana besleme + yardımcı devre şalteri ve ayrı uzatma kolları, sigorta atık bilgisi PLC'ye. TB1 (başlıkta feston sabit araba girişine en yakın nokta) ve TB2 (araba üzeri, güç kabloları remote I/O'ya uğramadan) klemens panelleri — monoblok IP66. Araba üzeri remote I/O paneli LVD12 — monoblok IP66. Operatör kabini remote I/O paneli LVD11 — min. IP55. Her ikisinde kapak açılınca devreye giren LED armatür + monofaze priz (30 mA RCBO) ve panele özel 24V DC güç kaynakları. Tüm panellerin önünde izolasyon halısı; panel üretici firması için ERDEMİR MÜHENDİSLİK onayı (Şartname 3.3.10, 3.3.2/18-20, 3.3.12/7) · EAE · Tahmini","hidden":false},{"id":"7ee21b3d-ec66-524a-9d8d-95c10dc64139","key":"aktarim-cc16-17-24","label":"Hız Kontrol Sistemi (Rejeneratif Doğrultucu + Sürücüler)","qty":2,"qtyManual":true,"unit":"takım","unitPrice":40000,"priceManual":true,"note":"Rejeneratif doğrultucu (IGBT kontrollü) ve DC baraya bağlı eviricilerden oluşan komple hız kontrol sistemi — vinç başına 1 ISU + 4 sürücü. ISU: ACS880-204-0420A-3 + hat filtresi ACS880-BLCL-13-5 (+C183 +C188), +V188 modül soğutma fanı, +E205 modül içi du/dt, BCU-02 kontrol ünitesi (R8i ISU kiti), FPNO-21 profinet kartı, ACS-AP-W panel kiti, DPMP-01 IP55 flush montaj kiti; rejeneratif modda şebeke kesilmesi/gerilim değişiminde hızlı sigorta ve IGBT hasarı olmadan devre dışı kalabilme. Ana kanca: ACS880-104-0300A-3 (+E205 du/dt, +V112 X50 yardımcı besleme konnektörü, BCU-02, FEN-31 enkoder kartı, FPNO-21, +N8015 MU crane lisansı, +N5050 crane control program, ACS-AP-W, DPMP-01). Yardımcı kanca ve araba: ACS880-104-0061A-3 (FEN-31, FPNO-21, N8015, N5050, ACS-AP-W, DPMP-01 + du/dt NOCH0070-60). Köprü: ACS880-104-0140A-3 (aynı opsiyonlar + du/dt BOCH-350A-7) — 2 köprü motoru tek sürücüden beslendiğinden motor girişlerinde uygun akım kapasiteli termik koruma ve yardımcı kontağın hata devresine eklenmesi. Kapalı çevrim vektör kontrol, sıfır hızda maksimum moment, kademesiz hız; 40°C'de her 5 dk'da 1 dk nominal akımın min. %150'si (kaldırmada min. %180); tüm sürücü çıkışlarında du/dt şok bobini; ağır şart güç değerleri motor etiket gücünün altında olmayacak; >30 kg üniteler için panelde raylı-tekerlekli çıkarma sistemi; devreye alma-parametre-izleme yazılımı ve panel kapağında sökülebilir LCD gösterge paneli. Açık çevrim salınım önleme (anti-sway) fonksiyonu N5050 crane control program kapsamındadır (Şartname 3.3.5, 3.3.8/40, Soru Formu 5.1-5.5) · ABB · Tahmini","hidden":false},{"id":"3313febd-d59d-5ed6-b36c-7d2a5a7f08f1","key":"aktarim-cc16-17-25","label":"PLC Sistemi (S7-1500 + ET200MP)","qty":2,"qtyManual":true,"unit":"takım","unitPrice":13000,"priceManual":true,"note":"CPU 1513-1 PN (6ES7513-1AM03-0AB0) + SIMATIC S7 12 MB hafıza kartı; LVD11 ve LVD12 için ET200MP IM 155-5 MF HF (6ES7155-5MU00-0CN0) hafıza kartlı; DI 16×24VDC HF (6ES7521-1BH00-0AB0), DQ 16×24VDC/0,5A HF (6ES7522-1BH01-0AB0), AI 8×U/I HF (6ES7531-7NF00-0AB0), AI 8×U/R/RTD/TC HF (6ES7531-7PF00-0AB0) — tüm CPU ve I/O modülleri HF tipi, her ünite (kanca, araba, köprü) bitiminde min. %20 yedek; profinet siviçler 6GK5224-0BA00-2AC2 (elektrik odası), 6GK5208-0BA00-2AC2 (araba ve kabin); yıldız topoloji (seri giriş/çıkış yok), metal endüstriyel profinet soketler, SCADA için yedek port (Şartname 3.3.7, Soru Formu 5.22-5.33) · SIEMENS · Tahmini","hidden":false},{"id":"b9f01119-1348-5c38-91f9-4b59bb3144d8","key":"aktarim-cc16-17-26","label":"HMI Dokunmatik Ekranlar","qty":4,"qtyManual":true,"unit":"adet","unitPrice":1500,"priceManual":true,"note":"Elektrik odası ve operatör kabini için 12 inç dokunmatik grafik display HMI: MTP1200 (6AV2123-3MB32-0AW0). Genel görünüm, ünite sayfaları, sürücü/ISU akım-gerilim-hız-pozisyon, I/O status, network arıza, alarm/geçmiş alarm, şifreli ayarlar ve SİSTEM sayfaları; ekran tasarımı Dijital Ek-14 referans tasarıma uygun (Şartname 3.3.7/9, 3.3.8/44, Soru Formu 5.26) · SIEMENS · Tahmini","hidden":false},{"id":"da92f328-263a-57e9-864b-7605c56d5688","key":"aktar